 if(a==='preview-job'){S.job=Number(t.dataset.index);S.page=1;render();return;}
 if(a==='page-prev'||a==='page-next'){S.page+=a==='page-prev'?-1:1;render();return;}
 if(a==='log'){const text=await(await fetch('/api/builds/'+S.batch.id+'/'+t.dataset.index+'/log')).text();modal('Build log',`<pre>${esc(text)}</pre>`);return;}
